/**
 * npm run types: the state route's TypeScript types, generated from its JSON Schema (D-015). Each schema/*.json becomes
 * assets/src/types/<name>.d.ts; CI fails when the generated files differ from the committed ones. Until the state
 * route's schema lands (milestone 4) there is no schema and nothing is written.
 */
import { readdirSync, writeFileSync, mkdirSync } from 'node:fs';
import { basename, join } from 'node:path';

let schemas = [];
try {
	schemas = readdirSync( 'schema' ).filter( ( f ) => f.endsWith( '.json' ) );
} catch {
	schemas = [];
}
if ( schemas.length === 0 ) {
	console.log( 'Types: schema/ has no JSON Schema yet; nothing generated.' );
	process.exit( 0 );
}
const { compileFromFile } = await import( 'json-schema-to-typescript' );
mkdirSync( 'assets/src/types', { recursive: true } );
for ( const schema of schemas ) {
	const name = basename( schema, '.json' );
	const ts = await compileFromFile( join( 'schema', schema ), {
		bannerComment:
			'/* Generated by `npm run types` from schema/' +
			schema +
			'. Do not edit. */',
		style: { useTabs: true, singleQuote: true },
	} );
	writeFileSync( join( 'assets/src/types', `${ name }.d.ts` ), ts );
	console.log(
		`Types: assets/src/types/${ name }.d.ts from schema/${ schema }.`
	);
}
